      ?result2 qudt:numericValue ?value2 .
      FILTER(YEAR(?time2) = 2005)
      FILTER(?value2 > ?value)
    }
    BIND(MONTH(?time) AS ?month)
  }
}
ORDER BY ?month
LIMIT 1

